import math

def _cos(a, b):
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(x * x for x in b))
    if na == 0 or nb == 0:
        return 0.0
    return sum(x * y for x, y in zip(a, b)) / (na * nb)

def zero_shot(image_vec, label_vecs):
    scores = {lab: round(_cos(image_vec, v), 3) for lab, v in label_vecs.items()}
    best = sorted(scores.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
    return best, scores

def _norm(v):
    if isinstance(v, str):
        return v.strip().lower()
    return v

def field_accuracy(cases):
    hits, seen = {}, {}
    for case in cases:
        exp, pred = case['expected'], case['predicted']
        for field, value in exp.items():
            seen[field] = seen.get(field, 0) + 1
            if _norm(pred.get(field)) == _norm(value):
                hits[field] = hits.get(field, 0) + 1
    return {f: round(hits.get(f, 0) / n, 2) for f, n in seen.items()}
